import mpmath as mp

GUARD = 40
DELTA = 80

def _g3(ctx, n, L, y, nd):
    if n == 0:
        return ctx.mpf(0) if nd == 0 else ctx.ninf
    return L*n*n - 2*y*n + nd*ctx.ln(abs(n))

def _g2(ctx, n, L, y, nd):
    m = 2*n+1
    if m == 0:
        return ctx.ninf
    return L*(n*n+n) - y*(2*n+1) + nd*ctx.ln(abs(m))

def _local_maxes(ctx, roots, gfunc, L, y, nd):
    cands = set()
    for r in roots:
        base = int(ctx.floor(r))
        for delta in range(-4, 5):
            cands.add(base + delta)
    cands.update([-2, -1, 1, 2])
    best = {}
    for n in cands:
        if n == 0:
            continue
        g = gfunc(ctx, n, L, y, nd)
        if not ctx.isfinite(g):
            continue
        ok = True
        for d in (-1, 1):
            m = n + d
            if m == 0:
                continue
            gm = gfunc(ctx, m, L, y, nd)
            if gm > g + ctx.mpf('1e-60') * max(1, abs(g)):
                ok = False
                break
        if not ok:
            continue
        side = 1 if n > 0 else -1
        if side not in best or g > best[side][0]:
            best[side] = (g, n)
    return best

def _interval(ctx, nc, side, gfunc, L, y, nd, T, kind, maxsteps=30000000):
    lo = hi = nc
    # upward
    n = nc
    while True:
        n += 1
        if kind == 2:
            if side < 0 and n > -1:
                break
            g = gfunc(ctx, n, L, y, nd)
        else:
            if side < 0 and n > -1:
                break
            if side > 0 and n < 1:
                g = ctx.ninf
            else:
                g = gfunc(ctx, n, L, y, nd)
        if g >= T:
            hi = n
        else:
            break
        if abs(n) > maxsteps:
            break
    # downward
    n = nc
    while True:
        n -= 1
        if kind == 2:
            if side > 0:
