                    break
                g = gfunc(ctx, n, L, y, nd)
            else:
                g = gfunc(ctx, n, L, y, nd)
        else:
            if side > 0:
                if n < 1:
                    break
                g = gfunc(ctx, n, L, y, nd)
            else:
                g = gfunc(ctx, n, L, y, nd)
