    """theta_n at fixed precision, direct series."""
    if n == 1:
        return _sum2(ctx, z - ctx.pi/2, q, nd, wp)[0]
    if n == 2:
        return _sum2(ctx, z, q, nd, wp)[0]
    if n == 3:
        return _sum3(ctx, z, q, nd, wp)[0]
    if n == 4:
        return _sum3(ctx, z, -q, nd, wp)[0]
    raise ValueError("First argument expected to be 1, 2, 3 or 4")

def _pval(ctx, coeffs, x):
    s = ctx.mpf(0)
    for c in reversed(coeffs):
        s = s*x + c
    return s

def _poly_deriv(coeffs):
    return [coeffs[i+1]*(i+1) for i in range(len(coeffs)-1)]

def _modular_at(ctx, n, z, q, nd, wp):
    """theta_n at fixed precision via the Jacobi imaginary transformation."""
    with ctx.workprec(wp):
        logq = ctx.log(q)
        logq2 = ctx.pi**2 / logq
        q2 = ctx.e**logq2
        tau = logq / (ctx.j * ctx.pi)
        w = z / tau
        c0 = (-ctx.j * tau) ** ctx.mpf('-0.5')
        if n == 1:
            c0 = c0 * ctx.j
        a = ctx.mpf(1) / logq
        invtau = ctx.mpf(1) / tau
        # derivatives of exp(a*z^2)
        polys = [[ctx.mpf(1)]]
        for _ in range(nd):
            prev = polys[-1]
            d = _poly_deriv(prev)
            new = [ctx.mpf(0)] * (len(prev))
            for i, c in enumerate(prev):
                new[i] = new[i] + 2*a*z*c
            for i, c in enumerate(d):
                new[i] = new[i] + c
            polys.append(new)
        # F_m = d^m/dw^m theta_k(w, q2)
        if n == 3:
            kind = 3
            ww = w
            qq = q2
        elif n == 2:
            kind = 3
            ww = w
            qq = -q2
        elif n == 4:
            kind = 2
            ww = w
            qq = q2
        else:  # n == 1
            kind = 2
            ww = w - ctx.pi/2
            qq = q2
