                F.append(_sum3(ctx, ww, qq, m, wp)[0])
            else:
                F.append(_sum2(ctx, ww, qq, m, wp)[0])
        E = ctx.e**(a*z*z)
        total = ctx.mpc(0)
        for m in range(nd + 1):
            coef = ctx.binomial(nd, m) * _pval(ctx, polys[nd-m], z) * invtau**m
            total += coef * F[m]
        total *= E
        total *= c0
        return total

def _auto(ctx, compute_at, n, z, q, nd):
    base = ctx.prec
    P = base + 80
    S = compute_at(ctx, n, z, q, nd, P)
    P2 = P + DELTA
    S2 = compute_at(ctx, n, z, q, nd, P2)
    for _ in range(14):
        if S2 == 0 and S == 0:
            return S2
        tol = ctx.mpf(2)**(-(base + 10)) * max(abs(S2), ctx.mpf(2)**(-(base + 40)))
        diff = abs(S2 - S)
        if diff <= tol:
            return S2
        P = P2
        S = S2
        P2 = P + DELTA
        S2 = compute_at(ctx, n, z, q, nd, P2)
    return S2

