    z = ctx.convert(z)
    q = ctx.convert(q)
    nd = int(derivative)
    if n not in (1, 2, 3, 4):
        raise ValueError("First argument expected to be 1, 2, 3 or 4")
    if abs(q) >= 1:
        raise ValueError("abs(q) must be smaller than 1")
    if q == 0:
        return _direct_at(ctx, n, z, q, nd, ctx.prec)
    L = ctx.log(abs(q))
    # approximate number of series terms needed by the direct series
    est_terms = ctx.sqrt((ctx.prec + 120) * ctx.ln2 / (-L))
    if est_terms > 4000:
        return _auto(ctx, _modular_at, n, z, q, nd)
    return _auto(ctx, _direct_at, n, z, q, nd)
