def _jtheta_poly_derivative(coeffs):
    return [coeffs[i + 1]*(i + 1) for i in range(len(coeffs) - 1)]


def _jtheta_modular_at(ctx, n, z, q, nd, wp):
    """Evaluate theta_n through the Jacobi imaginary transformation.

    For a nome close to the unit circle, tau = log(q)/(pi*j) has a small
    positive imaginary part and tau' = -1/tau maps q to an extremely small
    nome q'.  The defining series for q' converge immediately.
    """
    with ctx.workprec(wp):
        logq = ctx.log(q)
        logq2 = ctx.pi**2 / logq
        q2 = ctx.e ** logq2
        tau = logq / (ctx.j * ctx.pi)
        w = z / tau
        c0 = (-ctx.j * tau) ** ctx.mpf('-0.5')
        if n == 1:
            c0 = c0 * ctx.j
        a = ctx.mpf(1) / logq
        invtau = ctx.mpf(1) / tau

        # Polynomials P_k with (d/dz)^k exp(a*z^2) = P_k(z) exp(a*z^2).
        polys = [[ctx.mpf(1)]]
        for _ in range(nd):
            prev = polys[-1]
            deriv = _jtheta_poly_derivative(prev)
            new = [ctx.mpf(0)] * len(prev)
            for i, c in enumerate(prev):
                new[i] = new[i] + 2*a*z*c
            for i, c in enumerate(deriv):
                new[i] = new[i] + c
            polys.append(new)

        if n == 3:
            kind = 3
            ww = w
            qq = q2
        elif n == 2:
            kind = 3
            ww = w
            qq = -q2
        elif n == 4:
            kind = 2
            ww = w
            qq = q2
        else:  # n == 1
            kind = 2
            ww = w - ctx.pi/2
            qq = q2

        F = []
        for m in range(nd + 1):
            if kind == 3:
                F.append(_jtheta_sum3(ctx, ww, qq, m, wp)[0])
            else:
                F.append(_jtheta_sum2(ctx, ww, qq, m, wp)[0])

        E = ctx.e ** (a*z*z)
        total = ctx.mpc(0)
        for m in range(nd + 1):
            coef = _comb(nd, m) * _jtheta_polyval(ctx, polys[nd - m], z) * invtau**m
            total += coef * F[m]
        total *= E
        total *= c0
        return total


def _jtheta_auto(ctx, compute_at, n, z, q, nd):
    """Repeatedly increase the working precision until the result stabilizes."""
    base = ctx.prec
    wp = base + 80
    value = compute_at(ctx, n, z, q, nd, wp)
    wp2 = wp + _JTHETA_DELTA
    value2 = compute_at(ctx, n, z, q, nd, wp2)
    for _ in range(14):
        if value2 == 0 and value == 0:
            return value2
        tol = ctx.mpf(2) ** (-(base + 10)) * max(
            abs(value2), ctx.mpf(2) ** (-(base + 40)))
        if abs(value2 - value) <= tol:
            return value2
        wp = wp2
        value = value2
        wp2 = wp + _JTHETA_DELTA
        value2 = compute_at(ctx, n, z, q, nd, wp2)
    return value2


@defun
def jtheta(ctx, n, z, q, derivative=0):
    z = ctx.convert(z)
    q = ctx.convert(q)
    nd = int(derivative)
    if nd < 0:
        raise ValueError("derivative must be a nonnegative integer")
    if n not in (1, 2, 3, 4):
        raise ValueError("First argument expected to be 1, 2, 3 or 4")
    if abs(q) >= 1:
        raise ValueError("abs(q) must be smaller than 1")

    if q == 0:
