                total += t
                count += 1
                if envelope < maxabs*eps:
                    break
            return total, maxabs, count

        disc = y*y - 2*L*nd
        if disc < 0:
            return total, ctx.mpf(0), 0
        sq = ctx.sqrt(disc)
        roots = [(y + sq) / (2*L), (y - sq) / (2*L)]
        best = _jtheta_local_maxes(ctx, roots, _jtheta_g3, L, y, nd)
        if not best:
            return total, ctx.mpf(0), 0
        gmax = max(v[0] for v in best.values())
        T = gmax - (wp + _JTHETA_GUARD)*ctx.ln2
        for side, (g, nc) in best.items():
            if g < T:
                continue
            lo, hi = _jtheta_interval(ctx, nc, side, _jtheta_g3, L, y, nd, T, 3)
            for n in range(lo, hi + 1):
                if n == 0:
                    continue
                logterm = logq*n*n + (2*ctx.j*n*z)
                coef = (2*ctx.j*n) ** nd
                t = coef * ctx.e ** logterm
                total += t
                a = abs(t)
                if a > maxabs:
                    maxabs = a
                count += 1
        return total, maxabs, count


def _jtheta_sum2(ctx, z, q, nd, wp):
    """Sum theta_2(z, q) and its z-derivatives at `wp` bits.

    Returns (value, max_abs_term, term_count).
    """
    with ctx.workprec(wp):
        L = ctx.log(abs(q))
        y = ctx.im(z)
        logq = ctx.log(q)
        total = ctx.mpc(0)
        maxabs = ctx.mpf(0)
        count = 0
        if nd == 0:
            if y == 0:
                n0 = 0
            else:
                r = y / L - ctx.mpf('0.5')
                n0 = int(ctx.floor(r + ctx.mpf('0.5')))
            eps = ctx.mpf(2) ** (-(wp + _JTHETA_GUARD))

            def term(n):
                return ctx.e ** (logq*(n*n + n) + ctx.j*(2*n + 1)*z)

            t = term(n0)
            total += t
            a = abs(t)
            maxabs = a
            count += 1
            k = 1
            stop_plus = stop_minus = False
            while not (stop_plus and stop_minus):
                if not stop_plus:
                    t = term(n0 + k)
                    a = abs(t)
                    if a > maxabs:
                        maxabs = a
                    if a < maxabs*eps:
                        stop_plus = True
                    else:
                        total += t
                        count += 1
                if not stop_minus:
                    t = term(n0 - k)
                    a = abs(t)
                    if a > maxabs:
                        maxabs = a
                    if a < maxabs*eps:
                        stop_minus = True
                    else:
                        total += t
                        count += 1
                k += 1
                if k > _JTHETA_MAX_TERMS:
                    break
            return total * ctx.nthroot(q, 4), maxabs, count

est_terms = ctx.sqrt((ctx.prec + 120) * ctx.ln2 / (-L))
if est_terms > 200:
    res = _jtheta_auto(ctx, _jtheta_modular_at, n, z, q, nd)
else:
    res = _jtheta_auto(ctx, _jtheta_direct_at, n, z, q, nd)
res = +res
if not ctx._im(z) and not ctx._im(q) and ctx._im(res) == 0:
    return ctx._re(res)
return res
